{
  "name": "@ninjaninja140/opencode-multi-account",
  "version": "1.1.0",
  "publishConfig": {
    "access": "public"
  },
  "description": "OpenCode plugin for managing multiple API accounts with automatic rotation when rate limits are reached.",
  "main": "dist/index.js",
  "exports": {
    ".": "./dist/index.js"
  },
  "type": "module",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "multi-account",
    "rate-limit",
    "api-rotation"
  ],
  "scripts": {
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "build": "tsc -p tsconfig.json",
    "prepublishOnly": "npm run build"
  },
  "authors": ["rahadiana nugraha <rahadiana@gmail.com>", "ninjaninja140"],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/rahadiana/opencode-multi-account.git"
  },
  "bugs": {
    "url": "https://github.com/rahadiana/opencode-multi-account/issues"
  },
  "homepage": "https://github.com/rahadiana/opencode-multi-account#readme",
  "license": "MIT",
  "devDependencies": {
    "@types/node": "^25.6.0",
    "tsx": "^4.20.6",
    "typescript": "^5.4.0"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  }
}
